// RunMACSuite applies the checks of MAC, and the checks that opts add, to
// a fresh subject of newSubject for each check.
func RunMACSuite[T crypto.MAC](t *testing.T, newSubject func() T, opts ...MACOption) {
	t.Helper()
	RunMACSuiteFromHandle(t, func(*MACHandle) T { return newSubject() }, opts...)
}

// RunMACSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunMACSuiteFromHandle[T crypto.MAC](t *testing.T, newSubject func(h *MACHandle) T, opts ...MACOption) {
	t.Helper()
	conform.Run(t, MACSuite(), macSubjects(newSubject), opts...)
}

// FuzzMACSuite registers on f the fuzz target of the property checks of
// callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzMACSuite[T crypto.MAC](
	f *testing.F,
	callable conform.Callable[crypto.MAC],
	newSubject func(h *MACHandle) T,
	opts ...MACOption,
) {
	f.Helper()
	conform.Fuzz(f, MACSuite(), callable, macSubjects(newSubject), opts...)
}

